const body = $input.first().json.body || {};

// Validate required fields
const items = body.items;
const source = body.source;
const fields = body.fields || ['energy_kcal', 'protein_g', 'fat_g', 'carbs_g', 'fiber_g', 'salt_g'];
const aggregate = body.aggregate || { method: 'sum' };
const pluginContext = body.plugin_context || {};

const errors = [];
if (!items || !Array.isArray(items) || items.length === 0) {
  errors.push('items (array) is required');
}
if (!source || typeof source !== 'string') {
  errors.push('source (string) is required');
}

// Validate items structure
if (items && Array.isArray(items)) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (!item.name) {
      errors.push(`items[${i}].name is required`);
    }
  }
}

// Check valid sources
const validSources = ['openfoodfacts', 'ciqual', 'custom_api'];
if (source && !validSources.includes(source)) {
  errors.push(`Invalid source. Valid sources: ${validSources.join(', ')}`);
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Normalize items
const normalizedItems = items.map((item, index) => ({
  index: index,
  name: item.name.trim(),
  name_normalized: item.name.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''),
  quantity: item.quantity || 100,
  unit: item.unit || 'g',
  original: item
}));

return {
  json: {
    valid: true,
    items: normalizedItems,
    source: source,
    fields: fields,
    aggregate: {
      method: aggregate.method || 'sum',
      divide_by: aggregate.divide_by || null
    },
    plugin_context: pluginContext,
    custom_api_url: body.custom_api_url || null
  }
};

