// Helper function to find best match
function findBestMatch(name) {
  const normalized = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Exact match
  if (nutritionDatabase[normalized]) {
    return { data: nutritionDatabase[normalized], match_type: 'exact' };
  }

  // Partial match
  for (const key of Object.keys(nutritionDatabase)) {
    if (normalized.includes(key) || key.includes(normalized)) {
      return { data: nutritionDatabase[key], match_type: 'partial' };
    }
  }

  // Not found - return estimate
  return { data: null, match_type: 'not_found' };
}

// Helper function to convert unit to grams
function convertToGrams(quantity, unit) {
  const unitConversions = {
    'g': 1,
    'kg': 1000,
    'ml': 1, // Assuming density ~1 for liquids
    'l': 1000,
    'cl': 10,
    'c.s.': 15, // cuillère à soupe
    'c.c.': 5, // cuillère à café
    'tsp': 5,
    'tbsp': 15,
    'cup': 240,
    'piece': 50, // Average piece
    'pièce': 50,
    'unite': 50,
    'unité': 50
  };

  const unitLower = unit.toLowerCase();
  const multiplier = unitConversions[unitLower] || 1;
  return quantity * multiplier;
}

// Process each item
const enrichedItems = [];
let matched = 0;
let estimated = 0;
let notFound = 0;

