  const match = findBestMatch(item.name);
  const quantityInGrams = convertToGrams(item.quantity, item.unit);

  if (match.data) {
    // Calculate nutrition based on quantity
    const ratio = quantityInGrams / 100;
    const enrichedData = {};

    for (const field of fields) {
      if (match.data[field] !== undefined) {
        enrichedData[field] = Math.round(match.data[field] * ratio * 10) / 10;
      }
    }

    enrichedItems.push({
      ...item.original,
      nutrition: enrichedData,
      match_type: match.match_type,
      quantity_g: quantityInGrams
    });

    if (match.match_type === 'exact') {
      matched++;
    } else {
      estimated++;
    }
  } else {
    // Not found - add with null values
    const enrichedData = {};
    for (const field of fields) {
      enrichedData[field] = null;
    }

    enrichedItems.push({
      ...item.original,
      nutrition: enrichedData,
      match_type: 'not_found',
      quantity_g: quantityInGrams
    });
    notFound++;
  }
}

// Calculate aggregated values
const aggregated = {};
for (const field of fields) {
  let total = 0;
  let hasValue = false;

  for (const item of enrichedItems) {
    if (item.nutrition[field] !== null) {
      total += item.nutrition[field];
      hasValue = true;
    }
  }

  if (hasValue) {
    let finalValue = total;

    if (aggregate.method === 'average') {
      finalValue = total / enrichedItems.length;
    }

    if (aggregate.divide_by && aggregate.divide_by > 0) {
      finalValue = finalValue / aggregate.divide_by;
    }

    aggregated[field] = Math.round(finalValue * 10) / 10;
  } else {
    aggregated[field] = null;
  }
}

// Calculate total and per_serving if divide_by is provided
const result = {
  success: true,
  enriched_items: enrichedItems,
  aggregated: aggregate.divide_by ? {
    per_serving: aggregated,
    total: {}
  } : aggregated,
  data_quality: {
    matched: matched,
    estimated: estimated,
    not_found: notFound,
    confidence: (matched + estimated * 0.7) / items.length
  },
  meta: {
    source: 'openfoodfacts',
    items_count: items.length,
    fields: fields,
    aggregate_method: aggregate.method,
    servings: aggregate.divide_by || 1
  }
};

// If divide_by is set, also calculate total
if (aggregate.divide_by) {
  for (const field of fields) {
    if (aggregated[field] !== null) {
      result.aggregated.total[field] = Math.round(aggregated[field] * aggregate.divide_by * 10) / 10;
    }
  }
}

return { json: result };

// CIQUAL lookup - Phase 2 implementation
