    success: false,
    error: {
      code: 501,
      message: 'CIQUAL data source is planned for Phase 2. Please use openfoodfacts in the meantime.',
      status: 'NOT_IMPLEMENTED'
    },
    meta: {
      source: 'ciqual',
      items_count: input.items.length
    }
  }
};

// Custom API lookup
// For now, return a message indicating custom API needs configuration

const input = $input.first().json;

if (!input.custom_api_url) {
  return {
    json: {
      success: false,
      error: {
        code: 400,
        message: 'custom_api_url is required when using custom_api source',
        status: 'BAD_REQUEST'
      }
    }
  };
}

// In production, this would make HTTP requests to the custom API
return {
  json: {
    success: false,
    error: {
      code: 501,
      message: 'Custom API integration requires HTTP Request configuration. Contact n8n admin.',
      status: 'NOT_IMPLEMENTED'
    },
    meta: {
      source: 'custom_api',
      custom_api_url: input.custom_api_url,
      items_count: input.items.length
    }
  }
};

