// Helper function to find best match
function findBestMatch(name) {
  const normalized = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Exact match
  if (nutritionDatabase[normalized]) {
    return { data: nutritionDatabase[normalized], match_type: 'exact' };
  }

  // Partial match
  for (const key of Object.keys(nutritionDatabase)) {
    if (normalized.includes(key) || key.includes(normalized)) {
      return { data: nutritionDatabase[key], match_type: 'partial' };
    }
  }

  // Not found - return estimate
  return { data: null, match_type: 'not_found' };
}

// Helper function to convert unit to grams
function convertToGrams(quantity, unit) {
  const unitConversions = {
    'g': 1,
    'kg': 1000,
    'ml': 1, // Assuming density ~1 for liquids
    'l': 1000,
    'cl': 10,
    'c.s.': 15, // cuillère à soupe
    'c.c.': 5, // cuillère à café
    'tsp': 5,
    'tbsp': 15,
    'cup': 240,
    'piece': 50, // Average piece
    'pièce': 50,
    'unite': 50,
    'unité': 50
  };

  const unitLower = unit.toLowerCase();
  const multiplier = unitConversions[unitLower] || 1;
  return quantity * multiplier;
}

// Process each item
const enrichedItems = [];
let matched = 0;
let estimated = 0;
let notFound = 0;

for (const item of items) {
  const match = findBestMatch(item.name);
  const quantityInGrams = convertToGrams(item.quantity, item.unit);

  if (match.data) {
    // Calculate nutrition based on quantity
    const ratio = quantityInGrams / 100;
    const enrichedData = {};

    for (const field of fields) {
      if (match.data[field] !== undefined) {
        enrichedData[field] = Math.round(match.data[field] * ratio * 10) / 10;
      }
    }

    enrichedItems.push({
      ...item.original,
      nutrition: enrichedData,
      match_type: match.match_type,
      quantity_g: quantityInGrams
    });

    if (match.match_type === 'exact') {
      matched++;
    } else {
      estimated++;
    }
  } else {
    // Not found - add with null values
    const enrichedData = {};
    for (const field of fields) {
      enrichedData[field] = null;
    }

    enrichedItems.push({
      ...item.original,
      nutrition: enrichedData,
      match_type: 'not_found',
      quantity_g: quantityInGrams
    });
    notFound++;
  }
}

// Calculate aggregated values
const aggregated = {};
for (const field of fields) {
  let total = 0;
  let hasValue = false;

  for (const item of enrichedItems) {
    if (item.nutrition[field] !== null) {
      total += item.nutrition[field];
      hasValue = true;
    }
  }

  if (hasValue) {
    let finalValue = total;

    if (aggregate.method === 'average') {
      finalValue = total / enrichedItems.length;
    }

    if (aggregate.divide_by && aggregate.divide_by > 0) {
      finalValue = finalValue / aggregate.divide_by;
    }

    aggregated[field] = Math.round(finalValue * 10) / 10;
  } else {
    aggregated[field] = null;
  }
}

// Calculate total and per_serving if divide_by is provided
const result = {
  success: true,
  enriched_items: enrichedItems,
  aggregated: aggregate.divide_by ? {
    per_serving: aggregated,
    total: {}
  } : aggregated,
  data_quality: {
    matched: matched,
    estimated: estimated,
    not_found: notFound,
    confidence: (matched + estimated * 0.7) / items.length
  },
  meta: {
    source: 'openfoodfacts',
    items_count: items.length,
    fields: fields,
    aggregate_method: aggregate.method,
    servings: aggregate.divide_by || 1
  }
};

// If divide_by is set, also calculate total
if (aggregate.divide_by) {
  for (const field of fields) {
    if (aggregated[field] !== null) {
      result.aggregated.total[field] = Math.round(aggregated[field] * aggregate.divide_by * 10) / 10;
    }
  }
}

return { json: result };

